 60→  for (let i = 0; i < args.length; i++) {
 61→    switch (args[i]) {
 62→      case "--repo":
 63→        options.repo = args[++i];
 64→        if (!options.repo) {
 65→          console.error("Error: --repo requires a value (e.g., 'entireio/cli')");
