 72→      case "--dry-run":
 73→        options.dryRun = true;
 74→        break;
 75→      case "--limit":
 76→        options.limit = parseInt(args[++i], 10);
 77→        if (isNaN(options.limit) || options.limit <= 0) {
 78→          console.error("Error: --limit requires a positive integer");
 79→          process.exit(1);
 80→        }
 81→        break;
 82→      default:
 83→        console.error(`Unknown option: ${args[i]}`);
 84→        console.error("Usage: npx tsx scripts/backfill-search.ts [--repo <name>] [--with-transcripts] [--dry-run] [--limit <n>]");
 85→        process.exit(1);
