171→// --- Fetch with Retry ---
172→
173→async function fetchWithRetry(
174→  url: string,
175→  options: RequestInit,
176→): Promise<Response> {
177→  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
178→    try {
179→      const response = await fetch(url, options);
180→      // Retry on transient server errors and rate limits
181→      if (response.status >= 500 || response.status === 429) {
182→        if (attempt < MAX_RETRIES - 1) {
183→          const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
184→          await sleep(delay);
185→          continue;
186→        }
187→      }
188→      return response;
189→    } catch (err) {
190→      if (attempt < MAX_RETRIES - 1) {
191→        const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
192→        await sleep(delay);
193→        continue;
194→      }
195→      throw err;
196→    }
197→  }
198→  throw new Error("fetchWithRetry: exhausted retries");
199→}
