201→// --- Transcript Fetching ---
202→
203→async function fetchTranscriptExcerpt(
204→  repoFullName: string,
205→  checkpointId: string,
206→  agent: string,
207→  token: string,
208→): Promise<string | null> {
209→  const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
210→  const path = `${folder}/0/full.jsonl`;
211→
212→  // Encode each path segment individually (preserves / separators)
213→  const encodedPath = path.split("/").map(encodeURIComponent).join("/");
214→  const url = `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${CHECKPOINT_BRANCH}`;
215→
216→  try {
217→    const response = await fetchWithRetry(url, {
218→      headers: {
219→        Accept: "application/vnd.github.raw+json",
220→        Authorization: `Bearer ${token}`,
221→        "User-Agent": "entire-backfill",
222→        "X-GitHub-Api-Version": "2022-11-28",
223→      },
224→    });
225→
226→    if (!response.ok) {
227→      if (response.status === 404) {
228→        return null;
229→      }
230→      return null;
231→    }
232→
233→    const content = await response.text();
234→
235→    const parser = getParserForAgent(agent);
236→    const result = parser.parse(content);
237→
238→    if (result.messages.length === 0) {
239→      return null;
240→    }
241→
242→    // Extract first user message + first assistant message
243→    const parts: string[] = [];
244→    let charsUsed = 0;
245→
246→    for (const msg of result.messages) {
247→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
248→
249→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
250→      const text = msg.content.slice(0, remaining);
251→      parts.push(`[${msg.role}]: ${text}`);
252→      charsUsed += text.length;
253→
254→      // Only take the first user + first assistant
255→      if (msg.role === "assistant") break;
256→    }
257→
258→    return parts.join("\n") || null;
259→  } catch {
260→    return null;
261→  }
262→}
