514→async function main() {
515→  const options = parseArgs();
516→
517→  // Validate env vars
518→  if (!options.dryRun) {
519→    if (!process.env.TURBOPUFFER_API_KEY) {
520→      console.error("Error: TURBOPUFFER_API_KEY is required (or use --dry-run)");
521→      process.exit(1);
522→    }
523→    if (!process.env.OPENAI_API_KEY) {
524→      console.error("Error: OPENAI_API_KEY is required (or use --dry-run)");
525→      process.exit(1);
526→    }
527→  }
528→
529→  if (options.withTranscripts && !process.env.GITHUB_TOKEN) {
530→    console.error("Error: GITHUB_TOKEN is required when using --with-transcripts");
531→    process.exit(1);
532→  }
533→
534→  const db = createDb();
535→
536→  const tpuf = new Turbopuffer({
537→    apiKey: process.env.TURBOPUFFER_API_KEY ?? "",
538→  });
539→
540→  const openai = new OpenAI({
541→    apiKey: process.env.OPENAI_API_KEY ?? "",
542→  });
543→
544→  console.log("Backfill Search Index");
545→  console.log("=====================");
546→  if (options.dryRun) console.log("[DRY RUN MODE]");
547→  if (options.repo) console.log(`Repo filter: ${options.repo}`);
548→  if (options.limit) console.log(`Limit: ${options.limit} checkpoints per repo`);
549→  if (options.withTranscripts) console.log("Transcript fetching: enabled");
550→
551→  // Fetch repos with checkpoints
552→  let repoQuery = db
553→    .selectFrom("repos")
554→    .select(["id", "full_name", "checkpoint_count"])
555→    .where("checkpoint_count", ">", 0);
556→
557→  if (options.repo) {
