 55→// Uses FNV-1a 32-bit hash for fast, well-distributed IDs
 56→function hashToNumericId(checkpointId: string): number {
 57→  let hash = 0x811c9dc5; // FNV offset basis
 58→  for (let i = 0; i < checkpointId.length; i++) {
 59→    hash ^= checkpointId.charCodeAt(i);
 60→    hash = Math.imul(hash, 0x01000193); // FNV prime
 61→  }
 62→  return hash >>> 0; // unsigned 32-bit
 63→}
