25→function truncateToBytes(str: string | null, maxBytes: number): string | null {
26→  if (str === null) return null;
27→  if (str.length <= maxBytes) return str;
28→  const encoder = new TextEncoder();
29→  const encoded = encoder.encode(str);
30→  if (encoded.length <= maxBytes) return str;
31→  const truncated = encoded.slice(0, maxBytes);
32→  const decoder = new TextDecoder();
33→  return decoder.decode(truncated);
34→}
