215→// Index checkpoints into Turbopuffer for vector search
216→// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
217→// Returns the number of successfully indexed checkpoints
218→export async function indexCheckpoints(
219→  turbopufferApiKey: string,
220→  openaiApiKey: string,
221→  repoId: string,
222→  checkpoints: Array<{
223→    checkpoint_id: string;
224→    branch: string | null;
