226→    commit_author_username: string | null;
227→    created_at: string | null;
228→    commit_sha: string | null;
229→    commit_message: string | null;
230→    prompt: string | null;
231→    files_touched: string[] | null;
232→  }>,
233→): Promise<number> {
234→  // Build search text and filter out empty entries
235→  const validCheckpoints: Array<{
236→    checkpoint: (typeof checkpoints)[number];
237→    text: string;
238→  }> = [];
239→
240→  for (const cp of checkpoints) {
241→    const text = buildSearchText(cp);
242→    if (text.trim()) {
243→      validCheckpoints.push({ checkpoint: cp, text });
244→    }
245→  }
246→
247→  if (validCheckpoints.length === 0) {
248→    return 0;
249→  }
250→
251→  // Truncate texts for embedding model token limit
252→  const embeddingTexts = validCheckpoints.map((v) =>
253→    v.text.slice(0, MAX_EMBEDDING_CHARS),
254→  );
255→
256→  // Embed all texts in one batch call
257→  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);
258→
259→  // Build upsert payload (row-based format for Turbopuffer v1 API)
260→  const upserts = validCheckpoints.map(({ checkpoint, text }, i) => {
261→    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;
