    for (let i = 0; i < results.length; i++) {
      transcripts[batchStart + i] = results[i] ?? undefined;
      if (results[i]) found++;
    }
  }

  totalTranscripts += found;
  console.log(`    Transcripts: ${found}/${chunk.length} found`);
} else {
  transcripts = new Array(chunk.length).fill(undefined);
}

