122→export async function searchCheckpoints(
123→  turbopufferApiKey: string,
124→  openaiApiKey: string,
125→  githubId: number,
126→  query: string,
127→  filters?: { branch?: string },
128→  limit: number = 50,
129→): Promise<TurbopufferSearchResult[]> {
130→  const namespace = `checkpoints-gh-${githubId}`;
131→
132→  const headers = {
133→    Authorization: `Bearer ${turbopufferApiKey}`,
134→    "Content-Type": "application/json",
135→  };
136→
137→  const branchFilters = filters?.branch
138→    ? { branch: [["Eq", filters.branch]] }
139→    : undefined;
140→
141→  // Fire vector + BM25 queries in parallel
142→  const [vectorResults, bm25Results] = await Promise.all([
143→    // Vector cosine similarity (v1 API)
144→    (async (): Promise<TurbopufferQueryRow[]> => {
145→      const vector = await embedQuery(openaiApiKey, query);
146→      const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
147→      const body: Record<string, unknown> = {
148→        vector,
149→        top_k: limit,
150→        distance_metric: "cosine_distance",
151→        include_attributes: ["checkpoint_id"],
152→      };
153→      if (branchFilters) body.filters = branchFilters;
154→
155→      const resp = await fetch(url, {
156→        method: "POST",
157→        headers,
158→        body: JSON.stringify(body),
159→      });
160→      if (!resp.ok) {
161→        const text = await resp.text().catch(() => "");
162→        throw new Error(`Turbopuffer vector query failed (${resp.status}): ${text}`);
163→      }
164→      return (await resp.json()) as TurbopufferQueryResponse;
165→    })(),
166→
167→    // BM25 full-text search (v2 API)
168→    (async (): Promise<TurbopufferQueryRow[]> => {
169→      const url = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`;
170→      const body: Record<string, unknown> = {
171→        rank_by: ["text", "BM25", query],
172→        top_k: limit,
173→        include_attributes: ["checkpoint_id"],
174→      };
175→      if (branchFilters) body.filters = branchFilters;
176→
177→      const resp = await fetch(url, {
178→        method: "POST",
179→        headers,
180→        body: JSON.stringify(body),
181→      });
182→      if (!resp.ok) {
183→        const text = await resp.text().catch(() => "");
184→        throw new Error(`Turbopuffer BM25 query failed (${resp.status}): ${text}`);
185→      }
186→      return (await resp.json()) as TurbopufferQueryResponse;
187→    })(),
188→  ]);
189→
190→  // Merge via Reciprocal Rank Fusion (RRF)
191→  // score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
192→  const scores = new Map<string, number>();
193→
194→  for (let rank = 0; rank < vectorResults.length; rank++) {
195→    const id = vectorResults[rank].attributes?.checkpoint_id;
196→    if (id) {
197→      scores.set(id, (scores.get(id) ?? 0) + 1 / (RRF_K + rank + 1));
198→    }
199→  }
200→
201→  for (let rank = 0; rank < bm25Results.length; rank++) {
202→    const id = bm25Results[rank].attributes?.checkpoint_id;
203→    if (id) {
204→      scores.set(id, (scores.get(id) ?? 0) + 1 / (RRF_K + rank + 1));
205→    }
206→  }
207→
208→  // Sort by RRF score descending, take top `limit`
209→  const sorted = [...scores.entries()]
210→    .sort((a, b) => b[1] - a[1])
211→    .slice(0, limit);
212→
213→  return sorted.map(([checkpoint_id]) => ({ checkpoint_id }));
214→}
