26→function truncateToBytes(str: string | null, maxBytes: number): string | null {
27→  if (str === null) return null;
28→  if (str.length <= maxBytes) return str;
29→  const encoder = new TextEncoder();
30→  const encoded = encoder.encode(str);
31→  if (encoded.length <= maxBytes) return str;
32→  const truncated = encoded.slice(0, maxBytes);
33→  const decoder = new TextDecoder();
34→  return decoder.decode(truncated);
35→}
