console.log(`[search] vector results: ${vectorResults.length}, bm25 results: ${bm25Results.length}`);

// Log top results from each source with their raw scores
const topN = 5;
if (vectorResults.length > 0) {
  console.log(`[search] top ${topN} vector (cosine dist):`,
    vectorResults.slice(0, topN).map((r, i) => ({
      rank: i + 1,
      checkpoint_id: r.attributes?.checkpoint_id?.slice(0, 8),
      dist: r.dist?.toFixed(4),
    })),
  );
}
if (bm25Results.length > 0) {
  console.log(`[search] top ${topN} bm25:`,
    bm25Results.slice(0, topN).map((r, i) => ({
      rank: i + 1,
      checkpoint_id: r.attributes?.checkpoint_id?.slice(0, 8),
      dist: r.dist?.toFixed(4),
    })),
  );
}

// Merge via Reciprocal Rank Fusion (RRF)
// score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
const scores = new Map<string, { rrf: number; vectorRank: number | null; bm25Rank: number | null }>();

for (let rank = 0; rank < vectorResults.length; rank++) {
  const id = vectorResults[rank].attributes?.checkpoint_id;
  if (id) {
    const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
    entry.rrf += 1 / (RRF_K + rank + 1);
    entry.vectorRank = rank + 1;
    scores.set(id, entry);
  }
}

for (let rank = 0; rank < bm25Results.length; rank++) {
  const id = bm25Results[rank].attributes?.checkpoint_id;
  if (id) {
    const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
    entry.rrf += 1 / (RRF_K + rank + 1);
    entry.bm25Rank = rank + 1;
    scores.set(id, entry);
  }
}

// Sort by RRF score descending, take top `limit`
const sorted = [...scores.entries()]
  .sort((a, b) => b[1].rrf - a[1].rrf)
  .slice(0, limit);

// Log final merged results
console.log(`[search] top ${topN} RRF merged:`,
  sorted.slice(0, topN).map(([id, s]) => ({
    checkpoint_id: id.slice(0, 8),
    rrf: s.rrf.toFixed(6),
    vectorRank: s.vectorRank,
    bm25Rank: s.bm25Rank,
    source: s.vectorRank && s.bm25Rank ? "both" : s.vectorRank ? "vector-only" : "bm25-only",
  })),
);

return sorted.map(([checkpoint_id]) => ({ checkpoint_id }));

