// Fire vector + BM25 queries in parallel, gracefully degrade if either fails
const [vectorResult, bm25Result] = await Promise.all([
  // Vector cosine similarity (v1 API)
  (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
    try {
      const vector = await embedQuery(openaiApiKey, query);
      const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
      const body: Record<string, unknown> = {
        vector,
        top_k: limit,
        distance_metric: "cosine_distance",
        include_attributes: ["checkpoint_id"],
      };
      if (branchFilters) body.filters = branchFilters;

      const resp = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
      });
      if (!resp.ok) {
        const text = await resp.text().catch(() => "");
        return { rows: [], error: `vector query failed (${resp.status}): ${text}` };
      }
      const rows = (await resp.json()) as TurbopufferV1Row[];
      return { rows: rows.map((r) => ({ checkpoint_id: r.attributes?.checkpoint_id, dist: r.dist })) };
    } catch (err) {
      return { rows: [], error: `vector query error: ${err instanceof Error ? err.message : String(err)}` };
    }
  })(),

  // BM25 full-text search (v2 API)
  (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
    try {
      const url = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`;
      const body: Record<string, unknown> = {
        rank_by: ["text", "BM25", query],
        top_k: limit,
        include_attributes: ["checkpoint_id"],
      };
      if (branchFilters) body.filters = branchFilters;

      const resp = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
      });
      if (!resp.ok) {
        const text = await resp.text().catch(() => "");
        return { rows: [], error: `BM25 query failed (${resp.status}): ${text}` };
      }
      const data = (await resp.json()) as TurbopufferV2Response;
      return { rows: data.rows.map((r) => ({ checkpoint_id: r.checkpoint_id, dist: r.$dist })) };
    } catch (err) {
      return { rows: [], error: `BM25 query error: ${err instanceof Error ? err.message : String(err)}` };
    }
  })(),
]);

const vectorResults = vectorResult.rows;
const bm25Results = bm25Result.rows;

if (vectorResult.error) console.warn(`[search] ${vectorResult.error}`);
if (bm25Result.error) console.warn(`[search] ${bm25Result.error}`);

// If both failed, return empty so client falls back to local filtering
if (vectorResults.length === 0 && bm25Results.length === 0) {
  console.warn(`[search] both sources returned no results`);
  return [];
}

