 36→// Process a batch of search index messages
 37→export async function processSearchIndexBatch(
 38→  batch: MessageBatch<SearchIndexMessage>,
 39→  env: Env,
 40→): Promise<void> {
 41→  const batchStartTime = Date.now();
 42→  const batchId = generateBatchId();
 43→
 44→  const queueWaitTimes = batch.messages.map(
 45→    (msg) => Date.now() - msg.timestamp.getTime(),
 46→  );
 47→  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
 48→
 49→  log("batch_started", {
 50→    batchId,
 51→    queue: batch.queue,
 52→    count: batch.messages.length,
 53→    avgQueueWaitMs: avgMs(queueWaitTimes),
 54→    maxQueueWaitMs: maxWaitMs,
 55→  });
 56→
 57→  const processingTimes: number[] = [];
 58→  let successCount = 0;
 59→  let errorCount = 0;
 60→  let skippedCount = 0;
 61→
 62→  for (const msg of batch.messages) {
 63→    const msgStartTime = Date.now();
 64→    const { repoId, checkpointIds } = msg.body;
 65→
 66→    // Early return if API keys are missing — don't retry messages that can never succeed
 67→    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
 68→      log("skip_missing_api_keys", {
 69→        batchId,
 70→        repoId,
 71→        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
 72→        hasOpenai: !!env.OPENAI_API_KEY,
 73→      });
 74→      msg.ack();
 75→      skippedCount++;
 76→      continue;
 77→    }
 78→
 79→    try {
 80→      const db = getDb(env);
 81→
 82→      const repo = await db.repos.getById(repoId);
 83→      if (!repo) {
 84→        log("skip_repo_not_found", { batchId, repoId });
 85→        msg.ack();
 86→        skippedCount++;
 87→        continue;
 88→      }
 89→
 90→      const checkpoints = await db.checkpoints.getByIds(repoId, checkpointIds);
 91→
 92→      if (checkpoints.length === 0) {
 93→        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length });
 94→        msg.ack();
 95→        skippedCount++;
 96→        continue;
 97→      }
 98→
 99→      const indexed = await indexCheckpoints(
100→        env.TURBOPUFFER_API_KEY,
101→        env.OPENAI_API_KEY,
102→        repo.github_id,
103→        checkpoints.map((cp) => ({
104→          checkpoint_id: cp.checkpoint_id,
105→          branch: cp.branch,
106→          agent: cp.agent,
107→          commit_author_username: cp.commit_author_username,
108→          created_at: cp.created_at,
109→          commit_sha: cp.commit_sha,
110→          commit_message: cp.commit_message,
111→          prompt: cp.prompt,
112→          files_touched: cp.files_touched,
113→        })),
114→      );
115→
116→      const processingMs = Date.now() - msgStartTime;
117→      processingTimes.push(processingMs);
118→
119→      log("message_processed", {
120→        batchId,
121→        repoId,
122→        requested: checkpointIds.length,
123→        found: checkpoints.length,
124→        indexed,
125→        processingMs,
126→        attempt: msg.attempts,
127→      });
128→
129→      msg.ack();
130→      successCount++;
131→    } catch (err) {
132→      const processingMs = Date.now() - msgStartTime;
133→      processingTimes.push(processingMs);
134→      errorCount++;
135→
136→      log("message_error", {
137→        batchId,
138→        repoId,
139→        checkpointCount: checkpointIds.length,
140→        attempt: msg.attempts,
141→        processingMs,
142→        error: err instanceof Error ? err.message : String(err),
143→      });
144→
145→      // Retry on transient failures (max_retries configured in wrangler.jsonc)
146→      msg.retry();
147→    }
148→  }
149→
150→  const totalBatchTimeMs = Date.now() - batchStartTime;
151→
152→  log("batch_complete", {
153→    batchId,
154→    count: batch.messages.length,
155→    successCount,
156→    errorCount,
157→    skippedCount,
158→    totalBatchTimeMs,
159→    avgProcessingMs: avgMs(processingTimes),
160→    throughputPerMin:
161→      totalBatchTimeMs > 0
162→        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
163→        : 0,
164→  });
165→}
