299→// Index checkpoints into Turbopuffer for vector search
300→// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
301→// Returns the number of successfully indexed checkpoints
302→export async function indexCheckpoints(
303→  turbopufferApiKey: string,
304→  openaiApiKey: string,
305→  githubId: number,
306→  checkpoints: Array<{
307→    checkpoint_id: string;
308→    branch: string | null;
309→    agent: string | null;
310→    commit_author_username: string | null;
311→    created_at: string | null;
312→    commit_sha: string | null;
313→    commit_message: string | null;
314→    prompt: string | null;
315→    files_touched: string[] | null;
316→    transcript?: string | null;
317→  }>,
318→): Promise<number> {
319→  // Build search text and filter out empty entries
320→  const validCheckpoints: Array<{
321→    checkpoint: (typeof checkpoints)[number];
322→    text: string;
323→  }> = [];
324→
325→  for (const cp of checkpoints) {
326→    const text = buildSearchText(cp);
327→    if (text.trim()) {
328→      validCheckpoints.push({ checkpoint: cp, text });
329→    }
330→  }
331→
332→  if (validCheckpoints.length === 0) {
333→    return 0;
334→  }
335→
336→  // Truncate texts for embedding model token limit
337→  const embeddingTexts = validCheckpoints.map((v) =>
338→    v.text.slice(0, MAX_EMBEDDING_CHARS),
339→  );
340→
341→  // Embed all texts in one batch call
342→  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);
343→
344→  // Build upsert payload (row-based format for Turbopuffer v1 API)
345→  const upserts = validCheckpoints.map(({ checkpoint, text }, i) => {
346→    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;
347→    return {
348→      id: hashToNumericId(checkpoint.checkpoint_id),
349→      vector: embeddings[i],
350→      attributes: {
351→        checkpoint_id: checkpoint.checkpoint_id,
352→        branch: checkpoint.branch,
353→        agent: checkpoint.agent,
354→        author: checkpoint.commit_author_username,
355→        created_at: checkpoint.created_at,
356→        commit_sha: checkpoint.commit_sha,
357→        commit_message: truncateToBytes(
358→          checkpoint.commit_message,
359→          MAX_FILTERABLE_BYTES,
360→        ),
361→        prompt: truncateToBytes(checkpoint.prompt, MAX_FILTERABLE_BYTES),
362→        files_touched: truncateToBytes(filesTouchedStr, MAX_FILTERABLE_BYTES),
363→        text: truncateToBytes(text, MAX_TEXT_BYTES),
364→      },
365→    };
366→  });
367→
368→  // Upsert to Turbopuffer
369→  const namespace = `checkpoints-gh-${githubId}`;
370→  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}`;
371→
372→  const resp = await fetch(url, {
373→    method: "POST",
374→    headers: {
375→      Authorization: `Bearer ${turbopufferApiKey}`,
376→      "Content-Type": "application/json",
377→    },
378→    body: JSON.stringify({
379→      upserts,
380→      distance_metric: "cosine_distance",
381→      schema: {
382→        text: {
383→          type: "string",
384→          filterable: false,
385→          full_text_search: {
386→            language: "english",
387→            stemming: true,
388→            remove_stopwords: true,
389→          },
390→        },
391→      },
392→    }),
393→  });
394→
395→  if (!resp.ok) {
396→    const errText = await resp.text().catch(() => "");
397→    throw new Error(`Turbopuffer upsert failed (${resp.status}): ${errText}`);
398→  }
399→
400→  return validCheckpoints.length;
401→}
