import { describe, it, expect } from "vitest";
import {
  truncateToBytes,
  buildSearchText,
  hashToNumericId,
  mergeRRF,
  RRF_K,
  type SearchRow,
} from "./turbopuffer";

describe("truncateToBytes", () => {
  it("returns null for null input", () => {
    expect(truncateToBytes(null, 100)).toBeNull();
  });

  it("returns string unchanged when under limit", () => {
    expect(truncateToBytes("hello", 100)).toBe("hello");
  });

  it("returns string unchanged when exactly at limit", () => {
    expect(truncateToBytes("abc", 3)).toBe("abc");
  });

  it("truncates ASCII strings to byte limit", () => {
    const result = truncateToBytes("hello world", 5);
    expect(result).toBe("hello");
  });

  it("handles multi-byte UTF-8 characters correctly", () => {
    // emoji is 4 bytes in UTF-8
    const input = "a😀b";
    // "a" = 1 byte, "😀" = 4 bytes, "b" = 1 byte = 6 total
    const result = truncateToBytes(input, 5);
    // Should include "a" + "😀" = 5 bytes
    expect(result).toBe("a😀");
  });

  it("does not break mid-character", () => {
    // "é" is 2 bytes in UTF-8
    const input = "café";
    // c=1, a=1, f=1, é=2 = 5 total
    const result = truncateToBytes(input, 4);
    // Should truncate to "caf" (3 bytes) since "é" doesn't fit in remaining 1 byte
    expect(result?.length).toBeLessThanOrEqual(4);
  });
});

describe("buildSearchText", () => {
  it("includes all fields when present", () => {
    const result = buildSearchText({
      prompt: "add login feature",
      commit_message: "Implement login",
      files_touched: ["auth.ts", "login.tsx"],
    });
    expect(result).toBe(
      "Prompt: add login feature\nCommit: Implement login\nFiles: auth.ts, login.tsx",
    );
  });

  it("skips null fields", () => {
    const result = buildSearchText({
      prompt: "test",
      commit_message: null,
      files_touched: null,
    });
    expect(result).toBe("Prompt: test");
  });

  it("returns empty string when all fields are null", () => {
    const result = buildSearchText({
      prompt: null,
      commit_message: null,
      files_touched: null,
    });
    expect(result).toBe("");
  });

  it("includes transcript when provided", () => {
    const result = buildSearchText({
      prompt: "fix bug",
      commit_message: null,
      files_touched: null,
      transcript: "[user]: fix the auth bug\n[assistant]: I'll fix the auth validation",
    });
    expect(result).toContain("Transcript:");
    expect(result).toContain("fix the auth bug");
  });

  it("skips transcript when null", () => {
    const result = buildSearchText({
      prompt: "test",
      commit_message: null,
      files_touched: null,
      transcript: null,
    });
    expect(result).not.toContain("Transcript:");
  });
});

describe("hashToNumericId", () => {
  it("returns a positive 32-bit integer", () => {
    const id = hashToNumericId("abc123def456");
    expect(id).toBeGreaterThanOrEqual(0);
    expect(id).toBeLessThanOrEqual(0xffffffff);
  });

  it("is deterministic", () => {
    const a = hashToNumericId("test-checkpoint-id");
    const b = hashToNumericId("test-checkpoint-id");
    expect(a).toBe(b);
  });

  it("produces different IDs for different inputs", () => {
    const a = hashToNumericId("checkpoint-1");
    const b = hashToNumericId("checkpoint-2");
    expect(a).not.toBe(b);
  });
});

describe("mergeRRF", () => {
  function makeRows(...ids: string[]): SearchRow[] {
    return ids.map((id, i) => ({
      checkpoint_id: id,
      dist: i * 0.1,
    }));
  }

  it("merges results from both sources", () => {
    const vector = makeRows("a", "b", "c");
    const bm25 = makeRows("b", "d", "a");

    const merged = mergeRRF(vector, bm25, 10);

    // "a" and "b" appear in both, should have higher RRF scores
    const ids = merged.map((r) => r.checkpoint_id);
    expect(ids).toContain("a");
    expect(ids).toContain("b");
    expect(ids).toContain("c");
    expect(ids).toContain("d");

    // Items in both sources should rank higher
    const bothItems = merged.filter((r) => r.vectorRank !== null && r.bm25Rank !== null);
    const singleItems = merged.filter((r) => r.vectorRank === null || r.bm25Rank === null);
    expect(bothItems[0].rrf).toBeGreaterThan(singleItems[0].rrf);
  });

  it("handles vector-only results", () => {
    const vector = makeRows("a", "b");
    const bm25: SearchRow[] = [];

    const merged = mergeRRF(vector, bm25, 10);
    expect(merged).toHaveLength(2);
    expect(merged[0].vectorRank).toBe(1);
    expect(merged[0].bm25Rank).toBeNull();
  });

  it("handles bm25-only results", () => {
    const vector: SearchRow[] = [];
    const bm25 = makeRows("x", "y");

    const merged = mergeRRF(vector, bm25, 10);
    expect(merged).toHaveLength(2);
    expect(merged[0].bm25Rank).toBe(1);
    expect(merged[0].vectorRank).toBeNull();
  });

  it("handles empty inputs", () => {
    const merged = mergeRRF([], [], 10);
    expect(merged).toHaveLength(0);
  });

  it("respects limit parameter", () => {
    const vector = makeRows("a", "b", "c", "d", "e");
    const bm25 = makeRows("f", "g", "h", "i", "j");

    const merged = mergeRRF(vector, bm25, 3);
    expect(merged).toHaveLength(3);
  });

  it("calculates correct RRF scores", () => {
    const vector = makeRows("a");
    const bm25 = makeRows("a");

    const merged = mergeRRF(vector, bm25, 10);
    expect(merged).toHaveLength(1);

    // rank 1 in both: 1/(60+1) + 1/(60+1) = 2/61
    const expected = 2 / (RRF_K + 1);
    expect(merged[0].rrf).toBeCloseTo(expected, 10);
    expect(merged[0].vectorRank).toBe(1);
    expect(merged[0].bm25Rank).toBe(1);
  });

  it("ranks item at top of both sources higher than item at top of one", () => {
    // "a" is rank 1 in vector, rank 1 in bm25
    // "b" is rank 2 in vector only
    const vector = makeRows("a", "b");
    const bm25 = makeRows("a");

    const merged = mergeRRF(vector, bm25, 10);
    expect(merged[0].checkpoint_id).toBe("a");
    expect(merged[1].checkpoint_id).toBe("b");
  });

  it("skips rows with undefined checkpoint_id", () => {
    const vector: SearchRow[] = [
      { checkpoint_id: "a", dist: 0.1 },
      { checkpoint_id: undefined, dist: 0.2 },
      { checkpoint_id: "b", dist: 0.3 },
    ];

    const merged = mergeRRF(vector, [], 10);
    expect(merged).toHaveLength(2);
    expect(merged.map((r) => r.checkpoint_id)).toEqual(["a", "b"]);
  });

  it("deduplicates same checkpoint appearing in both sources", () => {
    const vector = makeRows("a", "b", "c");
    const bm25 = makeRows("c", "b", "a");

    const merged = mergeRRF(vector, bm25, 10);
    const ids = merged.map((r) => r.checkpoint_id);
    // No duplicates
    expect(new Set(ids).size).toBe(ids.length);
    expect(merged).toHaveLength(3);
  });
});

